def f(g):
    from collections import Counter
    c=Counter(v for r in g for v in r); noise=c.most_common(1)[0][0]
    H,W=len(g),len(g[0])
    out=[[None]*4 for _ in range(4)]
    for i in range(H//3):
        for j in range(W//3):
            vals=[g[r][cc] for r in range(i*3,i*3+3) for cc in range(j*3,j*3+3)]
            nc=[v for v in vals if v!=noise]
            if nc:
                cc2=Counter(nc)
                top=max(cc2.items(), key=lambda kv:(kv[1],-kv[0]))[0]
            else:
                top=max(set(vals))  # or Counter(vals).most_common(1)[0][0]
            out[i][j]=top
    return out
